import math
from dataclasses import dataclass
from typing import Protocol


# Open/closed: add a shape by adding a class, never by editing total_area
@dataclass
class Circle:
    r: float
    def area(self) -> float:
        return math.pi * self.r ** 2

@dataclass
class Rect:
    w: float
    h: float
    def area(self) -> float:
        return self.w * self.h

def total_area(shapes) -> float:
    return sum(shape.area() for shape in shapes)


# Dependency inversion: depend on "something that can send", not on SMTP
class EmailSender(Protocol):
    def send(self, to: str, subject: str, body: str) -> None: ...

class SignupService:
    def __init__(self, sender: EmailSender):
        self.sender = sender

    def register(self, email: str) -> None:
        ...  # create the account
        self.sender.send(email, "Welcome!", "Thanks for signing up.")

# Inheritance: one subclass per combination
class EmailNotifier(Notifier): ...
class LoggedEmailNotifier(EmailNotifier): ...
class RetryingSmsNotifier(SmsNotifier): ...
class LoggedRetryingSmsNotifier(RetryingSmsNotifier): ...   # and so on


# Composition: small parts, combined freely
class EmailChannel:
    def send(self, user, message):
        print(f"email to {user}: {message}")

class SmsChannel:
    def send(self, user, message):
        print(f"sms to {user}: {message}")

class Notifier:
    def __init__(self, channels, logger=None):
        self.channels = channels
        self.logger = logger

    def notify(self, user, message):
        for channel in self.channels:
            channel.send(user, message)
        if self.logger:
            self.logger.info("notified %s", user)

alerts = Notifier(channels=[EmailChannel(), SmsChannel()])
alerts.notify("ana", "Your order shipped")

class StandardShipping:
    def cost(self, cart_total):
        return 0 if cart_total >= 50 else 5

class ExpressShipping:
    def cost(self, cart_total):
        return 15


# Factory: the one place that maps a name to a strategy
SHIPPING_OPTIONS = {"standard": StandardShipping, "express": ExpressShipping}

def make_shipping(option):
    if option not in SHIPPING_OPTIONS:
        raise ValueError(f"unknown shipping option: {option}")
    return SHIPPING_OPTIONS[option]()


# The caller depends only on "has a cost() method"
def checkout_total(cart_total, shipping):
    return cart_total + shipping.cost(cart_total)

print(checkout_total(40, make_shipping("standard")))   # 45


