type Listener<T> = (event: T) => void

class EventBus<T> {
  private listeners = new Set<Listener<T>>()

  subscribe(listener: Listener<T>): () => void {
    this.listeners.add(listener)
    return () => this.listeners.delete(listener)   // call it to unsubscribe
  }

  publish(event: T): void {
    for (const listener of this.listeners) listener(event)
  }
}

interface OrderShipped {
  orderId: number
  email: string
}

const shipped = new EventBus<OrderShipped>()
shipped.subscribe((e) => sendEmail(e.email, `Order ${e.orderId} is on its way`))
const stopAnalytics = shipped.subscribe((e) => track('order_shipped', e.orderId))

shipped.publish({ orderId: 42, email: 'ana@example.com' })
stopAnalytics()   // analytics stops listening; email keeps going

