// Your app's own interface
interface PaymentGateway {
  charge(amountCents: number, customerId: string): Promise<string>   // payment id
}

// Adapter: makes the vendor SDK look like PaymentGateway
class AcmePayAdapter implements PaymentGateway {
  constructor(private client: AcmePayClient) {}

  async charge(amountCents: number, customerId: string): Promise<string> {
    const result = await this.client.createPayment({
      amount: { value: (amountCents / 100).toFixed(2), currency: 'USD' },
      payer: customerId,
    })
    return result.paymentId
  }
}

// Decorator: same interface, adds logging around every call
class LoggingGateway implements PaymentGateway {
  constructor(private inner: PaymentGateway, private log: Logger) {}

  async charge(amountCents: number, customerId: string): Promise<string> {
    this.log.info(`charging ${customerId} ${amountCents} cents`)
    const id = await this.inner.charge(amountCents, customerId)
    this.log.info(`charged, payment ${id}`)
    return id
  }
}

const gateway: PaymentGateway = new LoggingGateway(new AcmePayAdapter(acmeClient), logger)

