// Request -> router -> controller -> model -> controller -> view -> response

// Model: data and business rules
class Order {
  constructor(public id: number, public status: 'paid' | 'shipped' | 'cancelled') {}

  cancel(): void {
    if (this.status === 'shipped') throw new Error('Shipped orders cannot be cancelled')
    this.status = 'cancelled'
  }
}

// View: presentation only
function orderView(order: Order) {
  return { id: order.id, status: order.status }
}

// Controller: thin. Parse input, call the model, choose the view.
app.post('/orders/:id/cancel', async (req, res) => {
  const order = await orders.findById(Number(req.params.id))
  if (!order) return res.status(404).json({ error: 'Order not found' })

  try {
    order.cancel()
  } catch (err) {
    return res.status(409).json({ error: (err as Error).message })
  }
  await orders.save(order)
  res.json(orderView(order))
})

